fn positive_integer_compositions(
    total: i32,
    parts: usize,
    minimum: i32,
    maximum: usize,
) -> Vec<Vec<i32>> {
    fn build(
        remaining: i32,
        parts_left: usize,
        minimum: i32,
        current: &mut Vec<i32>,
        results: &mut Vec<Vec<i32>>,
        maximum: usize,
    ) {
        if results.len() >= maximum {
            return;
        }
        if parts_left == 1 {
            if remaining >= minimum {
                current.push(remaining);
                results.push(current.clone());
                current.pop();
            }
            return;
        }
        let reserved = minimum.saturating_mul(parts_left.saturating_sub(1) as i32);
        for value in minimum..=remaining.saturating_sub(reserved) {
            current.push(value);
            build(
                remaining - value,
                parts_left - 1,
                minimum,
                current,
                results,
                maximum,
            );
            current.pop();
            if results.len() >= maximum {
                return;
            }
        }
    }

    if parts == 0 || minimum < 1 || total < minimum.saturating_mul(parts as i32) {
        return Vec::new();
    }
    let mut results = Vec::new();
    build(
        total,
        parts,
        minimum,
        &mut Vec::new(),
        &mut results,
        maximum,
    );
    results
}

