pub trait DecisionProvider {
    fn choose(
        &mut self,
        state: &GameState,
        request: &EngineDecisionRequest,
    ) -> Result<usize, EngineError>;

    fn choose_number(
        &mut self,
        _state: &GameState,
        request: &EngineDecisionRequest,
    ) -> Result<i32, EngineError> {
        let Some((minimum, _)) = decision_number_bounds(request) else {
            return Err(EngineError::new(format!(
                "decision {} is not a number selection",
                request.id
            )));
        };
        Ok(minimum)
    }

    fn choose_card_instance_ids(
        &mut self,
        state: &GameState,
        request: &EngineDecisionRequest,
    ) -> Result<Vec<String>, EngineError> {
        let option_index = self.choose(state, request)?;
        let action = request.options.get(option_index).ok_or_else(|| {
            EngineError::new(format!(
                "decision provider selected invalid option {option_index} for {}",
                request.id
            ))
        })?;
        let decision_id = match request.choice.as_ref() {
            Some(DecisionChoice::CardSelection { decision_id, .. })
            | Some(DecisionChoice::CardOrder { decision_id, .. }) => decision_id,
            _ => {
                return Err(EngineError::new(format!(
                    "decision {} is not a card selection",
                    request.id
                )));
            }
        };
        action
            .decisions
            .get(decision_id)
            .and_then(Value::as_array)
            .map(|values| {
                values
                    .iter()
                    .filter_map(Value::as_str)
                    .map(ToOwned::to_owned)
                    .collect()
            })
            .ok_or_else(|| {
                EngineError::new(format!(
                    "decision option {} has no card selection for {decision_id}",
                    action.id
                ))
            })
    }

    fn requests_explicit_priority_pass(&self, _player_id: &str) -> bool {
        false
    }

    fn allows_combat_declaration_revisions(&self, _player_id: &str) -> bool {
        false
    }

    fn observe_turn_completed(&mut self, _state: &GameState) {}

    fn is_cancelled(&self) -> bool {
        false
    }
}

pub struct RandomAi {
    rng: StdRng,
}

impl RandomAi {
    pub fn seeded(seed: u64) -> Self {
        Self {
            rng: StdRng::seed_from_u64(seed),
        }
    }
}

impl DecisionProvider for RandomAi {
    fn choose(
        &mut self,
        _state: &GameState,
        request: &EngineDecisionRequest,
    ) -> Result<usize, EngineError> {
        if request.options.is_empty() {
            return Err(EngineError::new("decision request has no legal options"));
        }
        Ok(self.rng.gen_range(0..request.options.len()))
    }

    fn choose_number(
        &mut self,
        _state: &GameState,
        request: &EngineDecisionRequest,
    ) -> Result<i32, EngineError> {
        let Some((minimum, maximum)) = decision_number_bounds(request) else {
            return Err(EngineError::new(format!(
                "decision {} is not a number selection",
                request.id
            )));
        };
        Ok(self.rng.gen_range(minimum..=maximum))
    }
}

pub fn decision_number_bounds(request: &EngineDecisionRequest) -> Option<(i32, i32)> {
    match request.choice.as_ref()? {
        DecisionChoice::NumberSelection {
            minimum, maximum, ..
        } if maximum >= minimum => Some((*minimum, *maximum)),
        _ => None,
    }
}

pub fn validate_decision_card_instance_ids(
    request: &EngineDecisionRequest,
    selected: &[String],
) -> Result<(), EngineError> {
    let (candidates, minimum, maximum, ordered) = match request.choice.as_ref() {
        Some(DecisionChoice::CardSelection {
            candidate_card_instance_ids,
            minimum,
            maximum,
            ..
        }) => (candidate_card_instance_ids, *minimum, *maximum, false),
        Some(DecisionChoice::CardOrder {
            card_instance_ids, ..
        }) => (
            card_instance_ids,
            card_instance_ids.len(),
            card_instance_ids.len(),
            true,
        ),
        _ => {
            return Err(EngineError::new(format!(
                "decision {} is not a card selection",
                request.id
            )));
        }
    };
    if selected.len() < minimum || selected.len() > maximum {
        return Err(EngineError::new(format!(
            "decision {} requires {minimum}..={maximum} cards, received {}",
            request.id,
            selected.len()
        )));
    }
    let unique = selected.iter().collect::<BTreeSet<_>>();
    if unique.len() != selected.len() {
        return Err(EngineError::new(format!(
            "decision {} contains duplicate cards",
            request.id
        )));
    }
    if selected
        .iter()
        .any(|instance_id| !candidates.contains(instance_id))
    {
        return Err(EngineError::new(format!(
            "decision {} contains a card outside its candidates",
            request.id
        )));
    }
    if ordered && selected.len() != candidates.len() {
        return Err(EngineError::new(format!(
            "decision {} must order every candidate card",
            request.id
        )));
    }
    Ok(())
}

