pub struct RandomClientPool {
    seed: u64,
    clients: BTreeMap<String, StdRng>,
    decisions: Vec<ClientDecisionTrace>,
    findings: Vec<SimulationAuditFinding>,
    last_stack_ids: BTreeSet<String>,
}

impl RandomClientPool {
    pub fn seeded(seed: u64) -> Self {
        Self {
            seed,
            clients: BTreeMap::new(),
            decisions: Vec::new(),
            findings: Vec::new(),
            last_stack_ids: BTreeSet::new(),
        }
    }

    pub fn decisions(&self) -> &[ClientDecisionTrace] {
        &self.decisions
    }

    pub fn findings(&self) -> &[SimulationAuditFinding] {
        &self.findings
    }

    fn record_finding(&mut self, code: &str, message: impl Into<String>, decision_sequence: usize) {
        let message = message.into();
        if self
            .findings
            .iter()
            .any(|finding| finding.code == code && finding.message == message)
        {
            return;
        }
        self.findings.push(SimulationAuditFinding {
            code: code.to_string(),
            severity: "error".to_string(),
            message,
            decision_sequence: Some(decision_sequence),
        });
    }
}

impl DecisionProvider for RandomClientPool {
    fn choose(
        &mut self,
        state: &GameState,
        request: &EngineDecisionRequest,
    ) -> Result<usize, EngineError> {
        let decision_sequence = self.decisions.len() + 1;
        if request.options.is_empty() {
            return Err(EngineError::new(format!(
                "client {} received an empty decision request",
                request.player_id
            )));
        }
        match state
            .players
            .iter()
            .find(|player| player.id == request.player_id)
        {
            None => self.record_finding(
                "unknown_decision_client",
                format!("decision addressed to unknown player {}", request.player_id),
                decision_sequence,
            ),
            Some(player) if player.has_lost => self.record_finding(
                "decision_for_eliminated_player",
                format!(
                    "decision addressed to eliminated player {}",
                    request.player_id
                ),
                decision_sequence,
            ),
            Some(_) => {}
        }
        if request
            .options
            .iter()
            .any(|option| option.player_id != request.player_id)
        {
            self.record_finding(
                "decision_option_wrong_owner",
                format!(
                    "decision {} contains an option owned by another player",
                    request.id
                ),
                decision_sequence,
            );
        }
        let option_ids = request
            .options
            .iter()
            .map(|option| option.id.as_str())
            .collect::<BTreeSet<_>>();
        if option_ids.len() != request.options.len() {
            self.record_finding(
                "duplicate_decision_option_id",
                format!("decision {} contains duplicate option IDs", request.id),
                decision_sequence,
            );
        }
        if request.kind == DecisionKind::Priority {
            let priority_player_id = state
                .priority_player
                .and_then(|index| state.players.get(index))
                .map(|player| player.id.as_str());
            if priority_player_id != Some(request.player_id.as_str()) {
                self.record_finding(
                    "priority_request_wrong_player",
                    format!(
                        "priority decision {} addressed to {}, state priority is {:?}",
                        request.id, request.player_id, priority_player_id
                    ),
                    decision_sequence,
                );
            }
        }
        for instance_id in duplicate_zone_object_ids(state) {
            self.record_finding(
                "duplicate_zone_object",
                format!("card instance {instance_id} appears in more than one zone"),
                decision_sequence,
            );
        }
        let current_stack_ids = state
            .stack
            .iter()
            .map(|object| object.id.clone())
            .collect::<BTreeSet<_>>();
        if let Some(previous) = self.decisions.last()
            && !self.last_stack_ids.is_disjoint(&current_stack_ids)
            && (previous.state.turn_number != state.turn_number
                || previous.state.step != state.step)
        {
            self.record_finding(
                "phase_advanced_during_stack_cycle",
                format!(
                    "game advanced from turn {} {:?} to turn {} {:?} during a stack cycle",
                    previous.state.turn_number, previous.state.step, state.turn_number, state.step,
                ),
                decision_sequence,
            );
        }

        let client_seed = stable_client_seed(self.seed, &request.player_id);
        let client = self
            .clients
            .entry(request.player_id.clone())
            .or_insert_with(|| StdRng::seed_from_u64(client_seed));
        let selected_option_index = client.gen_range(0..request.options.len());
        let selected_action = request.options[selected_option_index].clone();
        self.decisions.push(ClientDecisionTrace {
            sequence: decision_sequence,
            client_id: request.player_id.clone(),
            state: decision_state_summary(state),
            request: request.clone(),
            selected_option_index,
            selected_action,
        });
        self.last_stack_ids = current_stack_ids;
        Ok(selected_option_index)
    }

    fn choose_number(
        &mut self,
        _state: &GameState,
        request: &EngineDecisionRequest,
    ) -> Result<i32, EngineError> {
        let Some((minimum, maximum)) = decision_number_bounds(request) else {
            return Err(EngineError::new(format!(
                "decision {} is not a number selection",
                request.id
            )));
        };
        let client_seed = stable_client_seed(self.seed, &request.player_id);
        let client = self
            .clients
            .entry(request.player_id.clone())
            .or_insert_with(|| StdRng::seed_from_u64(client_seed));
        Ok(client.gen_range(minimum..=maximum))
    }
}

