                reset_after_leaving_battlefield(&mut card);
                self.state.players[owner_index].library.push(card);
                self.record_event(
                    "abilitySourcePutOnLibrary",
                    Some(stack_object.controller.clone()),
                    Some(instance_id),
                    json!({ "position": "top" }),
                );
