                let source_id = stack_object.card.instance_id.clone();
                let source = self.state.players.iter_mut().find_map(|player| {
                    player
                        .graveyard
                        .iter()
                        .position(|card| card.instance_id == source_id)
                        .map(|position| player.graveyard.remove(position))
                });
                let Some(mut source) = source else {
                    return Ok(());
                };
                let player_index = self.player_index(&player_id)?;
                let mut pile = Vec::with_capacity(count.saturating_add(1));
                source.flags.insert("faceDown".to_string(), true);
                pile.push(source);
                for _ in 0..count {
                    let Some(mut card) = self.state.players[player_index].library.pop() else {
                        break;
                    };
                    card.flags.insert("faceDown".to_string(), true);
                    pile.push(card);
                }
