                    if !revealed_ids.contains(card.instance_id.as_str()) {
                        return true;
                    }
                    if selected_ids.contains(&card.instance_id) {
                        selected_cards.push(card.clone());
                    } else {
                        rest.push(card.clone());
                    }
                    false
